CREATE TABLE IF NOT EXISTS yonghu (id SERIAL PRIMARY KEY, zhanghao TEXT UNIQUE, mima TEXT, mingcheng TEXT, juese TEXT);
CREATE TABLE IF NOT EXISTS zuowu (id INTEGER PRIMARY KEY, mingcheng TEXT, shengyujie TEXT, xushui_xishu DOUBLE PRECISION, xufei_xishu DOUBLE PRECISION, shiyi_turang TEXT, mubiao_shidu DOUBLE PRECISION, tuijian_shuifen TEXT, tuijian_feiliao TEXT, shuoming TEXT);
CREATE TABLE IF NOT EXISTS zuowu_jieduan (id SERIAL PRIMARY KEY, zuowu_id INTEGER, jieduan TEXT, xushui_xishu DOUBLE PRECISION, xufei_xishu DOUBLE PRECISION, mubiao_shidu_min DOUBLE PRECISION, mubiao_shidu_max DOUBLE PRECISION, nongyi_tishi TEXT);
CREATE TABLE IF NOT EXISTS turang (id INTEGER PRIMARY KEY, zhidi TEXT, rongzhong DOUBLE PRECISION, chitian_chishuiliang DOUBLE PRECISION, ph DOUBLE PRECISION, dian_daolv DOUBLE PRECISION, qita TEXT);
CREATE TABLE IF NOT EXISTS shebei (id INTEGER PRIMARY KEY, mingcheng TEXT, leixing TEXT, zhuangtai TEXT, shuixiang DOUBLE PRECISION, feixiang DOUBLE PRECISION, liuliang DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS feiliao (id INTEGER PRIMARY KEY, mingcheng TEXT, dan DOUBLE PRECISION, lin DOUBLE PRECISION, jia DOUBLE PRECISION);
CREATE TABLE IF NOT EXISTS jiance (id SERIAL PRIMARY KEY, zuowu_id INTEGER, shengyujie TEXT, turang_shidu DOUBLE PRECISION, turang_wendu DOUBLE PRECISION, kongqi_shidu DOUBLE PRECISION, guangzhao DOUBLE PRECISION, dian_daolv DOUBLE PRECISION, jilu_shijian TEXT);
CREATE TABLE IF NOT EXISTS tianqi (id SERIAL PRIMARY KEY, yubaoriqi TEXT UNIQUE, zuigao_wendu DOUBLE PRECISION, zuidi_wendu DOUBLE PRECISION, kongqi_shidu DOUBLE PRECISION, jiangyu_gailv DOUBLE PRECISION, jiangyu_liang DOUBLE PRECISION, tianqi_leixing TEXT, zhengfa_liang DOUBLE PRECISION, diqu TEXT, shuju_laiyuan TEXT, gengxin_shijian TEXT);
CREATE TABLE IF NOT EXISTS yuce (id SERIAL PRIMARY KEY, zuowu_id INTEGER, yuce_tianshu INTEGER, xushui_json TEXT, xufei_json TEXT, shidu_json TEXT, fenxi TEXT, tianqi_shuoming TEXT, jilu_shijian TEXT);
CREATE TABLE IF NOT EXISTS juece (id SERIAL PRIMARY KEY, jiance_id INTEGER, zuowu_id INTEGER, zhuangtai TEXT, feili_zhuangtai TEXT, guangai_liang DOUBLE PRECISION, shifei_liang DOUBLE PRECISION, beng_yunxing DOUBLE PRECISION, yuanyin TEXT, jilu_shijian TEXT);
CREATE TABLE IF NOT EXISTS baogao (id SERIAL PRIMARY KEY, biaoti TEXT, chuangjian_shijian TEXT, gengxin_shijian TEXT, zuowu TEXT, zhaiyao TEXT, zhuangtai TEXT, daochuren TEXT, daochu_zhuangtai TEXT, neirong_json TEXT);
CREATE TABLE IF NOT EXISTS zhiling (id SERIAL PRIMARY KEY, shebei_id INTEGER, guangai_liang DOUBLE PRECISION, shifei_liang DOUBLE PRECISION, beng_yunxing DOUBLE PRECISION, zhuangtai TEXT, chuangjian_shijian TEXT, xiafa_shijian TEXT, caozuoren TEXT, caozuo_beizhu TEXT);
CREATE TABLE IF NOT EXISTS fankui (id SERIAL PRIMARY KEY, zhiling_id INTEGER, shiji_guangai DOUBLE PRECISION, shiji_shifei DOUBLE PRECISION, zhuangtai TEXT, shangbao_shijian TEXT);
CREATE TABLE IF NOT EXISTS yujing (id INTEGER PRIMARY KEY, leixing TEXT, mingcheng TEXT, zuixiao DOUBLE PRECISION, zuida DOUBLE PRECISION, dengji TEXT, shuoming TEXT);
CREATE TABLE IF NOT EXISTS rizhi (id SERIAL PRIMARY KEY, caozuo_shijian TEXT, caozuo_leixing TEXT, caozuo_neirong TEXT, caozuoren TEXT);
CREATE TABLE IF NOT EXISTS moxing_canshu (mingcheng TEXT PRIMARY KEY, n INTEGER, mean_x DOUBLE PRECISION, mean_y DOUBLE PRECISION, var_x DOUBLE PRECISION, cov_xy DOUBLE PRECISION, gengxin_shijian TEXT);
CREATE TABLE IF NOT EXISTS ai_fenxi (id SERIAL PRIMARY KEY, request_id TEXT, zuowu_id INTEGER, moxing_mingcheng TEXT, moxing_banben TEXT, tishici_banben TEXT, jiangji_shiyong INTEGER, haoshi DOUBLE PRECISION, shuru_json TEXT, shuchu_json TEXT, cuowu_xinxi TEXT, zhixindu DOUBLE PRECISION, zhuangtai TEXT, jilu_shijian TEXT);
